import fs from 'node:fs/promises';
import { probeHub } from '../mcp-hub.js';

// Video is generated by the agent through the ComfyUI MCP server; this CLI only
// records the selection and checks that the configured ComfyUI target answers.

async function readKey(file) {
    if (!file) return '';
    let key;
    try {
        key = (await fs.readFile(file, 'utf8')).split(/\r?\n/, 1)[0].trim();
    } catch {
        throw new Error(`无法读取 ComfyUI 密钥文件: ${file}`);
    }
    if (!key) throw new Error('ComfyUI 密钥文件第一行为空。');
    return key;
}

export async function probeComfy(url, { fetchImpl = fetch, timeoutMs = 5000, headers } = {}) {
    const response = await fetchImpl(new URL('system_stats', url.replace(/\/?$/, '/')), {
        signal: AbortSignal.timeout(timeoutMs),
        ...(headers && Object.keys(headers).length ? { headers } : {}),
    });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const body = await response.json();
    return { version: body?.system?.comfyui_version || '' };
}

export default {
    id: 'comfy-mcp',
    task: 'video',
    label: 'ComfyUI MCP（非 API MiniMax H3 模板）',
    guide: 'providers/comfy-mcp.md',
    ledgerProviders: ['comfy.run_template', 'comfy.run_workflow', 'comfy.fetch_outputs', 'comfy.generate_image'],
    testedVersion: 'comfy-mcp 0.10.0',
    agentOnly: true,
    execution: 'agent',
    capabilities: ['text-to-video', 'image-to-video', 'audio-driven-video', 'pose-reference-video', 'multi-reference-video'],
    publicSettings: ['url', 'hubUrl'],
    fields: {
        url: { env: 'COMFYUI_URL', type: 'url' },
        apiKeyFile: { env: 'COMFYUI_API_KEY_FILE', type: 'path' },
        hubUrl: { env: 'COMFY_MCP_HUB_URL', type: 'mcp-url' },
        hubTokenFile: { env: 'COMFY_MCP_HUB_TOKEN_FILE', type: 'path' },
    },
    async doctor(settings, { fetchImpl }) {
        if (settings.hubUrl || settings.hubTokenFile) {
            try {
                if (!settings.hubUrl) throw new Error('请配置 hubUrl 或 COMFY_MCP_HUB_URL。');
                const { version } = await probeHub(settings, { fetchImpl });
                return { ready: true, version: `MCP Hub${version ? ` / ComfyUI ${version}` : ''}`, hint: '' };
            } catch (error) {
                return { ready: false, version: '', hint: `MCP Hub 不可用: ${error.message}` };
            }
        }
        if (!settings.url) {
            return { ready: false, version: '', hint: '未配置 COMFYUI_URL 或 media.video.url；Agent 仍需自行注册 comfy-mcp。' };
        }
        try {
            const headers = {};
            const key = await readKey(settings.apiKeyFile);
            if (key) headers.Authorization = `Bearer ${key}`;
            const { version } = await probeComfy(settings.url, { fetchImpl, headers });
            return { ready: true, version: version ? `ComfyUI ${version}` : '', hint: '' };
        } catch (error) {
            return { ready: false, version: '', hint: `ComfyUI 目标不可达: ${error.message}` };
        }
    },
};
